/**
 * FundamentalPanel — dashboard section showing the company's fundamental
 * health, combining a MetricsRadar chart, a metrics table, and a
 * plain-language explanation generated by the LLM.
 *
 * Now also renders:
 *   - Growth Quality Score badge
 *   - PEG ratio badge
 *   - Analyst Price Targets panel
 *   - Insider Ownership & Activity row
 *   - Sector Comparison table
 */

import type { AnalystTargets, FundamentalResult, SectorComparison } from '../types'
import MetricsRadar from './charts/MetricsRadar'

// ── Props ─────────────────────────────────────────────────────────────────────

interface FundamentalPanelProps {
  result: FundamentalResult
  explanation: string
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function formatValue(value: number | null, unit: string | null): string {
  if (value === null) return '—'
  const formatted = Number.isInteger(value) ? String(value) : value.toFixed(2)
  return unit ? `${formatted} ${unit}` : formatted
}

/** Colour badge based on 0–100 score. */
function ScoreBadge({ score, label }: { score: number | null; label: string }) {
  if (score === null) return null
  const colour =
    score >= 70 ? 'bg-green-50 text-green-700' :
    score >= 40 ? 'bg-yellow-50 text-yellow-700' :
                  'bg-red-50 text-red-700'
  return (
    <span className={`rounded-full px-3 py-1 text-xs font-semibold ${colour}`} title={label}>
      {label}: {score.toFixed(0)} / 100
    </span>
  )
}

/** PEG ratio badge: green < 1, yellow 1–2, red > 2. */
function PegBadge({ peg }: { peg: number | null }) {
  if (peg === null) return <span className="text-xs text-gray-400">PEG: N/A</span>
  const colour =
    peg < 1   ? 'bg-green-50 text-green-700' :
    peg <= 2  ? 'bg-yellow-50 text-yellow-700' :
                'bg-red-50 text-red-700'
  const tip =
    peg < 1   ? 'Potentially undervalued vs growth' :
    peg <= 2  ? 'Fairly valued' :
                'Potentially expensive vs growth'
  return (
    <span className={`rounded-full px-3 py-1 text-xs font-semibold ${colour}`} title={tip}>
      PEG: {peg.toFixed(2)}
    </span>
  )
}

/** Analyst price target sub-panel. */
function AnalystTargetPanel({ at, currentPrice }: { at: AnalystTargets; currentPrice: number | null }) {
  const { mean_target, low_target, high_target, analyst_count, consensus } = at

  const consensusLabel: Record<string, { label: string; colour: string }> = {
    strongbuy:  { label: 'Strong Buy',  colour: 'bg-green-100 text-green-800' },
    buy:        { label: 'Buy',         colour: 'bg-green-50 text-green-700' },
    hold:       { label: 'Hold',        colour: 'bg-yellow-50 text-yellow-700' },
    sell:       { label: 'Sell',        colour: 'bg-red-50 text-red-700' },
    strongsell: { label: 'Strong Sell', colour: 'bg-red-100 text-red-800' },
  }

  const c = consensus ? consensusLabel[consensus.toLowerCase()] : null

  return (
    <div className="border border-gray-100 rounded-lg p-4 space-y-3">
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-semibold text-gray-700">
          Analyst Consensus
          {analyst_count != null && (
            <span className="ml-1 text-xs font-normal text-gray-400">({analyst_count} analysts)</span>
          )}
        </h3>
        {c && (
          <span className={`rounded-full px-3 py-1 text-xs font-semibold ${c.colour}`}>{c.label}</span>
        )}
      </div>

      {(mean_target != null || low_target != null || high_target != null) && (
        <div className="space-y-1">
          {/* Price range bar */}
          {currentPrice != null && low_target != null && high_target != null && low_target < high_target && (
            <div className="relative h-4 rounded-full bg-gray-100 overflow-hidden">
              {/* Current price marker */}
              {(() => {
                const range = high_target - low_target
                const pct = Math.max(0, Math.min(100, ((currentPrice - low_target) / range) * 100))
                return (
                  <div
                    className="absolute top-0 h-full w-1 bg-gray-700 rounded"
                    style={{ left: `${pct}%` }}
                    title={`Current: $${currentPrice.toFixed(2)}`}
                  />
                )
              })()}
              {/* Mean target marker */}
              {mean_target != null && (() => {
                const range = high_target - low_target
                const pct = Math.max(0, Math.min(100, ((mean_target - low_target) / range) * 100))
                return (
                  <div
                    className="absolute top-0 h-full w-1 bg-blue-500 rounded"
                    style={{ left: `${pct}%` }}
                    title={`Mean: $${mean_target.toFixed(2)}`}
                  />
                )
              })()}
            </div>
          )}
          <div className="flex justify-between text-xs text-gray-500">
            {low_target != null && <span>Low: ${low_target.toFixed(2)}</span>}
            {mean_target != null && <span className="font-medium text-blue-600">Mean: ${mean_target.toFixed(2)}</span>}
            {high_target != null && <span>High: ${high_target.toFixed(2)}</span>}
          </div>
        </div>
      )}
    </div>
  )
}

/** Sector comparison table: Up / Down / In-line indicators. */
function SectorComparisonPanel({ sc }: { sc: SectorComparison }) {
  const rows: { label: string; value: string | null }[] = [
    { label: 'P/E vs sector',    value: sc.pe_vs_sector },
    { label: 'P/B vs sector',    value: sc.pb_vs_sector },
    { label: 'Margin vs sector', value: sc.margin_vs_sector },
    { label: 'Growth vs sector', value: sc.growth_vs_sector },
  ]

  const colour = (v: string | null) =>
    v === 'Above'   ? 'text-green-600' :
    v === 'Below'   ? 'text-red-500' :
    v === 'In-line' ? 'text-gray-500' :
                      'text-gray-400'

  const arrow = (v: string | null) =>
    v === 'Above' ? '↑' : v === 'Below' ? '↓' : v === 'In-line' ? '→' : '—'

  return (
    <div className="border border-gray-100 rounded-lg p-4 space-y-2">
      <h3 className="text-sm font-semibold text-gray-700">
        Sector Context
        <span className="ml-1 text-xs font-normal text-gray-400">({sc.sector})</span>
      </h3>
      <div className="grid grid-cols-2 gap-x-4 gap-y-1">
        {rows.filter(r => r.value != null).map(({ label, value }) => (
          <div key={label} className="flex items-center gap-1 text-xs">
            <span className={`font-bold text-sm ${colour(value)}`}>{arrow(value)}</span>
            <span className="text-gray-600">{label}</span>
            <span className={`ml-auto font-medium ${colour(value)}`}>{value}</span>
          </div>
        ))}
      </div>
      <p className="text-xs text-gray-400">Relative to GICS sector median (±15% = In-line)</p>
    </div>
  )
}

// ── Component ─────────────────────────────────────────────────────────────────

export default function FundamentalPanel({ result, explanation }: FundamentalPanelProps) {
  const {
    pe_ratio,
    eps,
    pb_ratio,
    debt_to_equity,
    profit_margin,
    revenue_growth,
    dividend_yield,
    growth_quality_score,
    peg_ratio,
    analyst_targets,
    insider_ownership_pct,
    insider_net_activity,
    sector_comparison,
    score,
    warnings,
  } = result

  const metrics = [pe_ratio, eps, pb_ratio, debt_to_equity, profit_margin, revenue_growth, dividend_yield]

  // Insider activity chip colour.
  const insiderColour =
    insider_net_activity === 'Net Buying'  ? 'bg-green-50 text-green-700' :
    insider_net_activity === 'Net Selling' ? 'bg-red-50 text-red-700' :
                                             'bg-gray-50 text-gray-500'

  return (
    <section className="card space-y-5" aria-labelledby="fundamental-heading">

      {/* ── Heading + score badges ────────────────────────────────────────── */}
      <div className="flex flex-wrap items-center gap-2 justify-between">
        <h2 id="fundamental-heading" className="section-heading mb-0">
          Fundamental Analysis
        </h2>
        <div className="flex flex-wrap gap-2">
          <span className="rounded-full bg-blue-50 px-3 py-1 text-xs font-semibold text-blue-700">
            Score: {score} / 100
          </span>
          <ScoreBadge score={growth_quality_score} label="Growth Quality" />
          <PegBadge peg={peg_ratio} />
        </div>
      </div>

      {/* ── Radar chart ──────────────────────────────────────────────────── */}
      <MetricsRadar
        peRatio={pe_ratio.value}
        pbRatio={pb_ratio.value}
        debtToEquity={debt_to_equity.value}
        profitMargin={profit_margin.value}
        revenueGrowth={revenue_growth.value}
      />

      {/* ── Metrics table ────────────────────────────────────────────────── */}
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-gray-100 text-left text-xs font-semibold uppercase tracking-wide text-gray-400">
              <th className="pb-2 pr-4">Metric</th>
              <th className="pb-2 pr-4">Value</th>
              <th className="pb-2">What it means</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {metrics.map((m) => (
              <tr key={m.label} className="align-top">
                <td className="py-2 pr-4 font-medium text-gray-800 whitespace-nowrap">{m.label}</td>
                <td className="py-2 pr-4 tabular-nums text-gray-700 whitespace-nowrap">{formatValue(m.value, m.unit)}</td>
                <td className="py-2 text-gray-500">{m.interpretation ?? '—'}</td>
              </tr>
            ))}
            {/* Insider row */}
            {insider_ownership_pct != null && (
              <tr className="align-top">
                <td className="py-2 pr-4 font-medium text-gray-800 whitespace-nowrap">Insider Ownership</td>
                <td className="py-2 pr-4 tabular-nums text-gray-700 whitespace-nowrap">
                  {insider_ownership_pct.toFixed(1)}%
                  {insider_net_activity && (
                    <span className={`ml-2 rounded px-1.5 py-0.5 text-xs font-medium ${insiderColour}`}>
                      {insider_net_activity}
                    </span>
                  )}
                </td>
                <td className="py-2 text-gray-500">
                  Percentage of shares held by company executives and directors. Net activity = net buys/sells over ~6 months.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* ── Analyst targets ──────────────────────────────────────────────── */}
      {analyst_targets && (
        <AnalystTargetPanel at={analyst_targets} currentPrice={pe_ratio.value} />
      )}

      {/* ── Sector comparison ────────────────────────────────────────────── */}
      {sector_comparison && (
        <SectorComparisonPanel sc={sector_comparison} />
      )}

      {/* ── Plain-language explanation ────────────────────────────────────── */}
      {explanation && (
        <div className="border-t border-gray-100 pt-4 space-y-1">
          <h3 className="text-sm font-semibold text-gray-700">What this means for you</h3>
          <p className="text-sm leading-relaxed text-gray-600">{explanation}</p>
        </div>
      )}

      {/* ── Warning messages ─────────────────────────────────────────────── */}
      {warnings.length > 0 && (
        <ul className="space-y-1">
          {warnings.map((w, i) => (
            <li key={i} className="warning-banner">
              <span aria-hidden="true">⚠</span>
              {w}
            </li>
          ))}
        </ul>
      )}
    </section>
  )
}
